// Kaardimäng data shapes: the built catalog (src/content/kaardimang/catalog.json)
// and one pre-projected map view (public/kaardimang/maps/<version>/<view>.json).
// Both files are generated by scripts/kaardimang/build-map-data.ts.

import type { CapitalRole, ContinentId, WorldPartId } from './regions';

export type CatalogCapital = {
  id: string;
  countryId: string;
  nameEt: string;
  otherNames: string[];
  role: CapitalRole;
  roleLabelEt: string;
  lat: number | null;
  lon: number | null;
  nameSourceUrl: string;
  positionSourceUrl: string;
  verifiedOn: string;
  // A plain "Mis on X pealinn?" may use this capital as the one right answer.
  quizEligible: boolean;
  noteEt: string | null;
};

export type CountryStatus = 'un_member' | 'un_observer' | 'partially_recognised' | 'disputed';

export type CatalogCountry = {
  id: string; // ISO 3166-1 alpha-3 (Kosovo: XKX)
  iso2: string;
  m49: string | null;
  nameEt: string;
  // Omastav: "Mis on Jaapani pealinn?"
  nameGenEt: string;
  otherNamesEt: string[];
  officialNameEt: string;
  status: CountryStatus;
  // false: shown and explained in Uuri, never a scored target.
  target: boolean;
  worldPart: Exclude<WorldPartId, 'antarctica'>;
  subregions: string[];
  wellKnown: boolean;
  continent: ContinentId | null;
  m49Region: string | null;
  m49Subregion: string | null;
  flag: string;
  noteEt: string | null;
  capitals: CatalogCapital[];
  // Map views in which this country is large enough (or has a free marker) to tap.
  tappableIn?: string[];
};

export type KaardimangCatalog = {
  version: string;
  builtFrom: Record<string, { url: string; sha256: string }>;
  ekiAsOf: string;
  countries: CatalogCountry[];
  contextNames: Record<string, string>;
};

// role: t = a target of this view, s = special entity (explore only),
// c = context territory, n = a country outside this view's set (drawn, tappable
// as a wrong answer, named in feedback).
export type MapViewFeature = {
  id: string;
  role: 't' | 's' | 'c' | 'n';
  d: string;
  wp?: WorldPartId | null;
  ct?: ContinentId | null;
};

export type MapViewData = {
  id: string;
  version: string;
  width: number;
  height: number;
  sphere: string | null;
  features: MapViewFeature[];
  // Small countries (and the South Pole): a visible dot and a larger hit circle.
  markers: Array<{ id: string; x: number; y: number; r: number; hr: number }>;
  // Label anchor and the width of the country's land at this scale.
  labels: Record<string, [number, number, number]>;
  capitals: Array<{ id: string; countryId: string; x: number; y: number }>;
  // Ocean touch areas (Maailm and Antarktika views).
  areas: Array<{ id: string; kind: 'ocean'; d: string }>;
};
